def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    ink = next(v for row in grid for v in row if v != bg)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == ink]
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts)
    c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]

    # Complete the rectangular frame around the marked pattern.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if grid[r][c] == bg:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if grid[r][c] == bg:
                out[r][c] = 2

    return out

